  df64_split(b, bhi, blo);
  float e = julia_sub(julia_mul(ahi, bhi), p);
  e = julia_add(e, julia_mul(ahi, blo));
  e = julia_add(e, julia_mul(alo, bhi));
  e = julia_add(e, julia_mul(alo, blo));
  e = julia_add(e, julia_mul(a[1], b));
