      glsl::set_swizzle<1>(freq, map(state, context, frame, state.scaleY, static_cast<float>(1.0), static_cast<float>(100.0), static_cast<float>(20.0), static_cast<float>(3.0)));
      lf = glsl::Vec2(glsl::FloatExpr<2>(map(state, context, frame, state.loopScale, static_cast<float>(1.0), static_cast<float>(100.0), static_cast<float>(12.0), static_cast<float>(3.0))));
